#[kani::proof] #[kani::unwind(66)] fn LPb_weights64(){let xs:[[u32;4];64]=kani::any();let mut out=Vec::new();for raw in xs{let k=K{c0:CM31{a:M31(raw[0]),b:M31(raw[1])},c1:CM31{a:M31(raw[2]),b:M31(raw[3])}};let mut b=[0u8;16];k.write_le_bytes(&mut b);out.extend_from_slice(&b);}let at:usize=kani::any();kani::assume(at<1024);assert_eq!(out.len(),1024);assert_eq!(out[at],xs[at/16][(at%16)/4].to_le_bytes()[at%4]);kani::cover!(at==1023);}
